  "marketplace.features.offers.api.runtime.offer.product.id.does.not.match": "Offer product id does not match the selected options.",
  "marketplace.features.offers.api.runtime.offers.may.only.reference.active.catalog": "Offers may only reference active catalog items.",
  "marketplace.features.offers.api.runtime.seller.does.not.have.enough.active": "Seller does not have enough active supply to accept this offer.",
  "marketplace.features.offers.readModel.queries.offer.buyer.display.name.as.buyer": "\n  offer.*,\n  buyer.display_name AS buyer_display_name,\n  COALESCE((\n    SELECT SUM(\n      LEAST(\n        listing.quantity_cap,\n        GREATEST(\n          item.total_quantity - COALESCE(active_holds.held_quantity, 0),\n          0\n        )\n      )\n    )::integer\n    FROM marketplace_listing_pages AS listing\n    INNER JOIN marketplace_supply_items AS item\n      ON item.item_id = listing.inventory_item_id\n    LEFT JOIN (\n      SELECT item_id, SUM(quantity)::integer AS held_quantity\n      FROM marketplace_supply_holds\n      WHERE status = 'active'\n      GROUP BY item_id\n    ) AS active_holds\n      ON active_holds.item_id = item.item_id\n    WHERE listing.account_id = $1\n      AND listing.status = 'active'\n      AND listing.product_id = offer.product_id\n  ), 0)::integer AS seller_available_quantity,\n  EXISTS (\n    SELECT 1\n    FROM marketplace_buyer_offer_match_sell_list_pages AS cart\n    WHERE cart.seller_account_id = $1\n      AND cart.offer_id = offer.offer_id\n  ) AS in_sell_list",
  "marketplace.features.offers.readModel.queries.offer.not.found": "Offer not found.",
  "marketplace.features.offers.readModel.queries.offer.status.submitted.and.exists.select": "\n(\n  (\n    offer.status = 'submitted'\n    AND EXISTS (\n      SELECT 1\n      FROM marketplace_listing_pages AS listing\n      WHERE listing.account_id = $1\n        AND listing.status = 'active'\n        AND listing.product_id = offer.product_id\n    )\n  )\n  OR (\n    offer.status = 'accepted'\n    AND offer.accepted_seller_account_id = $1\n  )\n)",
  "marketplace.features.offers.readModel.schema.create.table.if.not.exists.marketplace": "\nCREATE TABLE IF NOT EXISTS marketplace_offer_pages (\n  offer_id text PRIMARY KEY,\n  buyer_account_id text NOT NULL,\n  catalog_catalog_item_id text NOT NULL,\n  product_id text NOT NULL,\n  item_title text NOT NULL,\n  item_subtitle text NULL,\n  selected_options jsonb NOT NULL DEFAULT '[]'::jsonb,\n  product_summary text NULL,\n  price_amount numeric(12,2) NOT NULL,\n  quantity_requested integer NOT NULL CHECK (quantity_requested > 0),\n  status text NOT NULL DEFAULT 'submitted',\n  accepted_seller_account_id text NULL,\n  accepted_at timestamptz NULL,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE INDEX IF NOT EXISTS marketplace_offer_pages_buyer_account_idx\n  ON marketplace_offer_pages (buyer_account_id, updated_at DESC);\n\nCREATE INDEX IF NOT EXISTS marketplace_offer_pages_catalog_catalog_item_idx\n  ON marketplace_offer_pages (catalog_catalog_item_id, status, updated_at DESC);\n\nCREATE INDEX IF NOT EXISTS marketplace_offer_pages_catalog_version_idx\n  ON marketplace_offer_pages (product_id, status, updated_at DESC);\n\nCREATE INDEX IF NOT EXISTS marketplace_offer_pages_selected_options_idx\n  ON marketplace_offer_pages USING gin (selected_options);\n\nCREATE TABLE IF NOT EXISTS marketplace_buyer_offer_match_sell_list_pages (\n  seller_account_id text NOT NULL,\n  offer_id text NOT NULL,\n  added_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now(),\n  PRIMARY KEY (seller_account_id, offer_id)\n);\n\nCREATE INDEX IF NOT EXISTS marketplace_buyer_offer_match_sell_list_pages_seller_idx\n  ON marketplace_buyer_offer_match_sell_list_pages (seller_account_id, updated_at DESC);\n",
