  "ordering.features.orders.integrations.supply.supplySourceSchema.create.table.if.not.exists.ordering": "\nCREATE TABLE IF NOT EXISTS ordering_market_listing_inputs (\n  listing_id text PRIMARY KEY,\n  seller_account_id text NOT NULL,\n  inventory_item_id text NOT NULL,\n  catalog_catalog_item_id text NOT NULL,\n  product_id text NOT NULL,\n  item_title text NULL,\n  item_subtitle text NULL,\n  selected_options jsonb NOT NULL DEFAULT '[]'::jsonb,\n  product_summary text NULL,\n  storage_location_name text NULL,\n  ship_from_code text NULL,\n  price_amount numeric(12, 2) NOT NULL,\n  quantity_cap integer NOT NULL CHECK (quantity_cap >= 0),\n  status text NOT NULL,\n  updated_at timestamptz NOT NULL\n);\n\nCREATE INDEX IF NOT EXISTS ordering_market_listing_inputs_lookup_idx\n  ON ordering_market_listing_inputs (product_id, status, price_amount, updated_at);\n\nCREATE INDEX IF NOT EXISTS ordering_market_listing_inputs_item_idx\n  ON ordering_market_listing_inputs (inventory_item_id, status, updated_at);\n\nCREATE TABLE IF NOT EXISTS ordering_inventory_item_inputs (\n  item_id text PRIMARY KEY,\n  seller_account_id text NOT NULL,\n  catalog_catalog_item_id text NOT NULL,\n  product_id text NOT NULL,\n  total_quantity integer NOT NULL CHECK (total_quantity >= 0),\n  updated_at timestamptz NOT NULL,\n  last_stream_version integer NOT NULL CHECK (last_stream_version >= 1)\n);\n\nCREATE INDEX IF NOT EXISTS ordering_inventory_item_inputs_lookup_idx\n  ON ordering_inventory_item_inputs (seller_account_id, catalog_catalog_item_id, product_id);\n\nCREATE TABLE IF NOT EXISTS ordering_inventory_hold_inputs (\n  hold_id text PRIMARY KEY,\n  item_id text NOT NULL,\n  seller_account_id text NOT NULL,\n  quantity integer NOT NULL CHECK (quantity >= 0),\n  status text NOT NULL,\n  released_at timestamptz NULL,\n  updated_at timestamptz NOT NULL,\n  last_stream_version integer NOT NULL CHECK (last_stream_version >= 1)\n);\n\nCREATE INDEX IF NOT EXISTS ordering_inventory_hold_inputs_item_idx\n  ON ordering_inventory_hold_inputs (item_id, status);\n\nCREATE TABLE IF NOT EXISTS ordering_offer_acceptance_inputs (\n  offer_id text PRIMARY KEY,\n  buyer_account_id text NOT NULL,\n  seller_account_id text NOT NULL,\n  catalog_catalog_item_id text NOT NULL,\n  product_id text NOT NULL,\n  item_title text NOT NULL,\n  item_subtitle text NULL,\n  selected_options jsonb NOT NULL DEFAULT '[]'::jsonb,\n  product_summary text NULL,\n  price_amount numeric(12, 2) NOT NULL,\n  quantity_requested integer NOT NULL CHECK (quantity_requested > 0),\n  accepted_at timestamptz NOT NULL,\n  updated_at timestamptz NOT NULL\n);\n\nCREATE TABLE IF NOT EXISTS ordering_payment_capture_inputs (\n  payment_id text PRIMARY KEY,\n  buyer_account_id text NOT NULL,\n  order_ids jsonb NOT NULL DEFAULT '[]'::jsonb,\n  amount numeric(12, 2) NOT NULL,\n  currency_code text NOT NULL,\n  processor_name text NOT NULL,\n  processor_payment_reference text NOT NULL,\n  processor_status text NOT NULL,\n  captured_at timestamptz NOT NULL,\n  updated_at timestamptz NOT NULL\n);\n",
  "ordering.features.orders.readModel.queries.select.page.order.id.page.source": "\n  SELECT\n    page.order_id,\n    page.source_type,\n    page.source_reference_id,\n    page.buyer_account_id,\n    buyer.display_name AS buyer_display_name,\n    page.seller_account_id,\n    seller.display_name AS seller_display_name,\n    page.shipping_option,\n    page.item_subtotal_amount::text AS item_subtotal_amount,\n    page.shipping_base_amount::text AS shipping_base_amount,\n    page.shipping_discount_amount::text AS shipping_discount_amount,\n    page.shipping_charge_amount::text AS shipping_charge_amount,\n    page.total_amount::text AS total_amount,\n    page.marketplace_sales_fee_amount::text AS marketplace_sales_fee_amount,\n    page.marketplace_checkout_fee_amount::text AS marketplace_checkout_fee_amount,\n    page.seller_net_amount::text AS seller_net_amount,\n    page.terms_schedule_id,\n    page.terms_agreement_id,\n    page.terms_resolved_at,\n    page.status,\n    page.created_at,\n    page.updated_at,\n    page.cancelled_at,\n    page.cancellation_reason,\n    page.ready_for_fulfillment_at,\n    COALESCE(line_stats.line_count, 0) AS line_count,\n    COALESCE(line_stats.total_quantity, 0) AS total_quantity\n  FROM ordering_order_pages AS page\n  LEFT JOIN ordering_account_pages AS buyer\n    ON buyer.account_id = page.buyer_account_id\n  LEFT JOIN ordering_account_pages AS seller\n    ON seller.account_id = page.seller_account_id\n  LEFT JOIN (\n    SELECT\n      order_id,\n      COUNT(*)::integer AS line_count,\n      COALESCE(SUM(quantity), 0)::integer AS total_quantity\n    FROM ordering_order_line_pages\n    GROUP BY order_id\n  ) AS line_stats\n    ON line_stats.order_id = page.order_id\n",
  "ordering.features.orders.readModel.schema.create.table.if.not.exists.ordering": "\nCREATE TABLE IF NOT EXISTS ordering_order_pages (\n  order_id text PRIMARY KEY,\n  source_type text NOT NULL,\n  source_reference_id text NULL,\n  buyer_account_id text NOT NULL,\n  seller_account_id text NOT NULL,\n  shipping_option text NOT NULL,\n  item_subtotal_amount numeric(12,2) NOT NULL,\n  shipping_base_amount numeric(12,2) NOT NULL,\n  shipping_discount_amount numeric(12,2) NOT NULL,\n  shipping_charge_amount numeric(12,2) NOT NULL,\n  total_amount numeric(12,2) NOT NULL,\n  marketplace_sales_fee_amount numeric(12,2) NOT NULL,\n  marketplace_checkout_fee_amount numeric(12,2) NOT NULL,\n  seller_net_amount numeric(12,2) NOT NULL,\n  terms_schedule_id text NULL,\n  terms_agreement_id text NULL,\n  terms_resolved_at timestamptz NOT NULL,\n  status text NOT NULL,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now(),\n  cancelled_at timestamptz NULL,\n  cancellation_reason text NULL,\n  ready_for_fulfillment_at timestamptz NULL\n);\n\nCREATE INDEX IF NOT EXISTS ordering_order_pages_buyer_idx\n  ON ordering_order_pages (buyer_account_id, updated_at DESC, order_id DESC);\n\nCREATE INDEX IF NOT EXISTS ordering_order_pages_seller_idx\n  ON ordering_order_pages (seller_account_id, updated_at DESC, order_id DESC);\n\nCREATE TABLE IF NOT EXISTS ordering_order_line_pages (\n  order_id text NOT NULL,\n  line_id text NOT NULL,\n  line_index integer NOT NULL,\n  listing_id text NOT NULL,\n  inventory_item_id text NOT NULL,\n  catalog_catalog_item_id text NOT NULL,\n  product_id text NOT NULL,\n  item_title text NOT NULL,\n  item_subtitle text NULL,\n  selected_options jsonb NOT NULL DEFAULT '[]'::jsonb,\n  product_summary text NULL,\n  unit_price_amount numeric(12,2) NOT NULL,\n  quantity integer NOT NULL CHECK (quantity > 0),\n  line_total_amount numeric(12,2) NOT NULL,\n  PRIMARY KEY (order_id, line_id)\n);\n\nCREATE INDEX IF NOT EXISTS ordering_order_line_pages_order_idx\n  ON ordering_order_line_pages (order_id, line_index ASC);\n\nCREATE INDEX IF NOT EXISTS ordering_order_line_pages_catalog_version_idx\n  ON ordering_order_line_pages (product_id);\n\nCREATE TABLE IF NOT EXISTS ordering_order_hold_pages (\n  hold_id text PRIMARY KEY,\n  order_id text NOT NULL,\n  seller_account_id text NOT NULL,\n  inventory_item_id text NOT NULL,\n  quantity integer NOT NULL CHECK (quantity > 0),\n  status text NOT NULL,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  released_at timestamptz NULL\n);\n\nCREATE INDEX IF NOT EXISTS ordering_order_hold_pages_order_idx\n  ON ordering_order_hold_pages (order_id, created_at ASC);\n",
