  "settlement.features.wallets.integrations.paymentSource.paymentSourceSchema.create.table.if.not.exists.settlement": "\nCREATE TABLE IF NOT EXISTS settlement_payment_sources (\n  payment_id text PRIMARY KEY,\n  buyer_account_id text NOT NULL,\n  order_ids jsonb NOT NULL DEFAULT '[]'::jsonb,\n  amount numeric(12,2) NOT NULL,\n  balance_credit_amount numeric(12,2) NOT NULL DEFAULT 0,\n  processor_amount numeric(12,2) NOT NULL DEFAULT 0,\n  currency_code text NOT NULL,\n  processor_name text NOT NULL,\n  processor_payment_reference text NOT NULL,\n  processor_status text NOT NULL,\n  status text NOT NULL,\n  failure_code text NULL,\n  failure_message text NULL,\n  created_at timestamptz NOT NULL,\n  updated_at timestamptz NOT NULL,\n  captured_at timestamptz NULL,\n  failed_at timestamptz NULL,\n  cancelled_at timestamptz NULL,\n  last_stream_version integer NOT NULL DEFAULT 0\n);\n\nCREATE INDEX IF NOT EXISTS settlement_payment_sources_status_idx\n  ON settlement_payment_sources (status, updated_at DESC, payment_id DESC);\n\nALTER TABLE settlement_payment_sources\n  ADD COLUMN IF NOT EXISTS balance_credit_amount numeric(12,2) NOT NULL DEFAULT 0;\n\nALTER TABLE settlement_payment_sources\n  ADD COLUMN IF NOT EXISTS processor_amount numeric(12,2) NOT NULL DEFAULT 0;\n\nCREATE TABLE IF NOT EXISTS settlement_refund_sources (\n  refund_id text PRIMARY KEY,\n  payment_id text NOT NULL,\n  order_ids jsonb NOT NULL DEFAULT '[]'::jsonb,\n  amount numeric(12,2) NOT NULL,\n  currency_code text NOT NULL,\n  reason text NOT NULL,\n  processor_name text NOT NULL,\n  processor_status text NOT NULL,\n  processor_refund_reference text NULL,\n  status text NOT NULL,\n  failure_code text NULL,\n  failure_message text NULL,\n  requested_at timestamptz NOT NULL,\n  updated_at timestamptz NOT NULL,\n  issued_at timestamptz NULL,\n  failed_at timestamptz NULL,\n  last_stream_version integer NOT NULL DEFAULT 0\n);\n\nCREATE INDEX IF NOT EXISTS settlement_refund_sources_payment_idx\n  ON settlement_refund_sources (payment_id, updated_at DESC, refund_id DESC);\n\nCREATE INDEX IF NOT EXISTS settlement_refund_sources_status_idx\n  ON settlement_refund_sources (status, updated_at DESC, refund_id DESC);\n",
  "settlement.features.wallets.readModel.queries.select.account.id.currency.code.pending": "\n  SELECT\n    account_id,\n    currency_code,\n    pending_balance_amount::text AS pending_balance_amount,\n    available_balance_amount::text AS available_balance_amount,\n    total_credited_amount::text AS total_credited_amount,\n    total_debited_amount::text AS total_debited_amount,\n    opened_at,\n    updated_at\n  FROM settlement_wallet_pages\n",
  "settlement.features.wallets.readModel.schema.create.table.if.not.exists.settlement": "\nCREATE TABLE IF NOT EXISTS settlement_wallet_pages (\n  account_id text PRIMARY KEY,\n  currency_code text NOT NULL,\n  pending_balance_amount numeric(12, 2) NOT NULL,\n  available_balance_amount numeric(12, 2) NOT NULL,\n  total_credited_amount numeric(12, 2) NOT NULL,\n  total_debited_amount numeric(12, 2) NOT NULL,\n  opened_at timestamptz NULL,\n  updated_at timestamptz NULL\n);\n\nCREATE TABLE IF NOT EXISTS settlement_ledger_entry_pages (\n  ledger_entry_id text PRIMARY KEY,\n  account_id text NOT NULL REFERENCES settlement_wallet_pages (account_id) ON DELETE CASCADE,\n  kind text NOT NULL,\n  direction text NOT NULL,\n  amount numeric(12, 2) NOT NULL,\n  currency_code text NOT NULL,\n  funds_status text NOT NULL,\n  order_id text NULL,\n  payment_id text NULL,\n  payout_id text NULL,\n  description text NULL,\n  posted_at timestamptz NOT NULL,\n  available_at timestamptz NULL,\n  updated_at timestamptz NOT NULL\n);\n\nCREATE INDEX IF NOT EXISTS settlement_ledger_entry_pages_account_idx\n  ON settlement_ledger_entry_pages (account_id, posted_at DESC, ledger_entry_id DESC);\n\nCREATE INDEX IF NOT EXISTS settlement_ledger_entry_pages_payout_idx\n  ON settlement_ledger_entry_pages (payout_id)\n  WHERE payout_id IS NOT NULL;\n",
